require_once __DIR__.'/../../includes/accounting_ui.php';acHandle(fn()=>($_POST['action']??'')==='account'?$ac->saveAccount($_POST):$ac->postManualJournal($_POST),'journals');$accounts=$ac->rows('SELECT * FROM ac_accounts WHERE school_id=? ORDER BY code',[$school]);ob_start();
