<p>Posted entries are preserved. Use reviewed reversals for corrections. Student receivable/advance controls can only be changed by the corresponding student financial workflows.</p>
<div class="card card-body table-responsive mb-3"><h4>Chart of accounts</h4><table class="table"><thead><tr><th>Code</th><th>Account</th><th>Type</th><th>Control</th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td><?= sanitize($a['code']) ?></td><td><?= sanitize($a['name']) ?></td><td><?= sanitize($a['type']) ?></td><td><?= sanitize($a['control_key']??'Custom') ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if($ac->can('settings')): ?><details class="mb-3"><summary>Add custom chart account</summary><?php acForm('account');acInput('code','Account code');acInput('name','Account name');acSelect('type','Account type',acChoices(['asset'=>'Asset','liability'=>'Liability','equity'=>'Equity / school fund','income'=>'Income','expense'=>'Expense','contra_income'=>'Contra-income']));acSubmit('Create account'); ?></details><?php endif; ?>
<?php if($ac->can('opening')): ?><details class="mb-3"><summary>Post reviewed journal / income / opening cash balance</summary><?php acForm('journal');acInput('date','Posting date',date('Y-m-d'),'date');acInput('description','Description / evidence reference'); ?><div class="table-responsive"><table class="table"><thead><tr><th>Account</th><th>Debit (NPR)</th><th>Credit (NPR)</th></tr></thead><tbody><?php for($i=0;$i<8;$i++): ?><tr><td><?php acSelect('lines['.$i.'][account_id]','Account',$accounts,'','id','name',false); ?></td><td><input class="form-control" name="lines[<?= $i ?>][debit]" type="number" min="0" step="0.01" value="0.00" aria-label="Debit row <?= $i+1 ?>"></td><td><input class="form-control" name="lines[<?= $i ?>][credit]" type="number" min="0" step="0.01" value="0.00" aria-label="Credit row <?= $i+1 ?>"></td></tr><?php endfor; ?></tbody></table></div><label><input type="checkbox" required name="confirm" value="1"> I verified the supporting documents and balanced debit / credit entries</label><?php acSubmit('Post balanced journal'); ?></details><?php endif; ?>
<div class="card card-body table-responsive"><h4>Recent posted journals</h4><table class="table"><thead><tr><th>Number</th><th>Date</th><th>Reference</th><th>Description</th><th>Debits</th><th>Credits</th></tr></thead><tbody><?php foreach($ac->rows('SELECT j.*,SUM(l.debit_minor) debit,SUM(l.credit_minor) credit FROM ac_journals j JOIN ac_journal_lines l ON l.journal_id=j.id WHERE j.school_id=? GROUP BY j.id ORDER BY j.id DESC LIMIT 100',[$school]) as $j): ?><tr><td><?= sanitize($j['number']) ?></td><td><?= sanitize(schoolDateLabel($j['posting_date'],'both','ymd')) ?></td><td><?= sanitize($j['reference_type'].' #'.$j['reference_id']) ?></td><td><?= sanitize($j['description']) ?></td><td><?= acMoney((int)$j['debit']) ?></td><td><?= acMoney((int)$j['credit']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php acRender('Chart of accounts & journals',ob_get_clean());
